<script setup lang="ts">import {ref,onMounted} from 'vue';import {go} from '../router';import {studies} from '../stores/studies';import {datasets} from '../stores/datasets';import {specs} from '../stores/specs';import {runs} from '../stores/runs';import {canWrite} from '../stores/auth';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';const name=ref(''),dataset=ref('demo-dataset'),spec=ref('demo-spec'),queries=ref('query_id,x,y\nNZ-Q01,10,10\nNZ-Q02,10,45\nNZ-Q03,10,80\nNZ-Q04,10,115\nNZ-Q05,10,160\nNZ-Q06,45,10\nNZ-Q07,45,45\nNZ-Q08,45,80\nNZ-Q09,45,115\nNZ-Q10,45,160\nNZ-Q11,80,10\nNZ-Q12,80,45\nNZ-Q13,80,80\nNZ-Q14,80,115\nNZ-Q15,80,160\nNZ-Q16,115,10\nNZ-Q17,115,45\nNZ-Q18,115,80\nNZ-Q19,115,115\nNZ-Q20,115,160\nNZ-Q21,160,10\nNZ-Q22,160,45\nNZ-Q23,160,80\nNZ-Q24,160,115\nNZ-Q25,160,160');const {error,busy,act}=useTask();onMounted(()=>Promise.all([studies.load(),datasets.load(),specs.load()]));function submit(){act(async()=>{await studies.create({name:name.value,dataset_id:dataset.value,spec_id:spec.value,query_coordinate_system:'local_meters',queries_csv:queries.value});name.value=''})}function execute(id:string){act(async()=>{const r=await runs.create({study_id:id});go('/results?run='+r.id)})}</script><template><PageHeading index="03 / 待估研究" title="把待估位置，与同一套模型一起锁定。" note="待估坐标仍用采样同一局部米制原点。允许查询已知位置，但待估点自身不重复；不自动做经纬度换算。"/><Notice :message="error"/><div class="two-col"><section><article v-for="r in studies.items.value" :key="r.id" class="study-row"><p class="eyebrow">KRIGING STUDY</p><h2>{{r.name}}</h2><p>{{r.queries.length}}个锁定待估点 · {{r.query_coordinate_system}}</p><div class="query-preview"><span v-for="q in r.queries.slice(0,6)" :key="q.query_id">{{q.query_id}} ({{q.x}},{{q.y}})</span></div><button v-if="canWrite()" :disabled="busy" @click="execute(r.id)">执行后台空间推断 →</button></article></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>创建空间研究</h2><label>研究名称<input v-model="name" required minlength="2"></label><label>采样批次<select v-model="dataset"><option v-for="r in datasets.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>变异函数口径<select v-model="spec"><option v-for="r in specs.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>待估CSV / 米<textarea v-model="queries" rows="11" required></textarea></label><button :disabled="busy">保存待估研究</button></form></div></template>
